function getLegacyTierIcon(tier) {
  const name = String(tier?.name || tier || '').toLowerCase();
  if (name.includes('goat')) return '👑';
  if (name.includes('legend')) return '🔥';
  if (name.includes('elite')) return '💎';
  if (name.includes('veteran')) return '🛡';
  return '⭐';
}

function getActivityTierIcon(tier) {
  const name = String(tier?.name || tier || '').toLowerCase();
  if (name.includes('grinder') || name.includes('icon')) return '💀';
  if (name.includes('dedicated') || name.includes('elite')) return '🏹';
  if (name.includes('active')) return '🚀';
  if (name.includes('casual') || name.includes('rookie')) return '⚡';
  return '🌱';
}

function normalizeActivityTierName(tier) {
  const name = String(tier?.name || tier || '').toLowerCase();
  if (name.includes('grinder') || name.includes('icon')) return 'Grinder';
  if (name.includes('dedicated') || name.includes('elite')) return 'Dedicated';
  if (name.includes('active')) return 'Active';
  if (name.includes('casual') || name.includes('rookie')) return 'Casual';
  return 'Inactive';
}

async function ensureUserAvatar(guildId, userId) {
  await pool.query(
    `INSERT INTO user_avatar (guild_id, user_id)
     VALUES ($1, $2)
     ON CONFLICT (guild_id, user_id) DO NOTHING`,
    [guildId, userId]
  );

  const result = await pool.query(
    `SELECT * FROM user_avatar WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  );

  return result.rows[0] || {
    equipped_top: 'Basic Tee',
    equipped_bottom: 'Plain Shorts',
    equipped_headwear: 'none',
    equipped_accessory: 'Ghost Wristband',
    equipped_footwear: 'Basic Sneakers',
    equipped_pet: 'none',
  };
}

async function awardUserBadge(guildId, userId, badgeKey, badgeLabel, badgeIcon, source = null) {
  await pool.query(
    `INSERT INTO user_badges (guild_id, user_id, badge_key, badge_label, badge_icon, source)
     VALUES ($1, $2, $3, $4, $5, $6)
     ON CONFLICT (guild_id, user_id, badge_key)
     DO UPDATE SET badge_label = $4, badge_icon = $5, source = COALESCE($6, user_badges.source)`,
    [guildId, userId, badgeKey, badgeLabel, badgeIcon, source]
  );
}

async function getUserStreamUrl(guildId, userId) {
  const result = await pool.query(
    `SELECT stream_url FROM guild_stream_links WHERE guild_id = $1 AND user_id = $2
     UNION
     SELECT stream_url FROM stream_links WHERE user_id = $2
     LIMIT 1`,
    [guildId, userId]
  );
  return result.rows[0]?.stream_url || null;
}

async function syncProfileBadges(guildId, userId, recognition = null) {
  const row = recognition || (await pool.query(
    `SELECT * FROM user_recognition WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  )).rows[0] || {};

  const legacyScore = Number(row.legacy_score || 0);
  const activityPoints = Number(row.activity_points || 0);
  const championships = Number(row.championships || 0);
  const sportsbookWins = Number(row.sportsbook_wins || 0);
  const sportsbookProfit = Number(row.sportsbook_profit || 0);

  const legacyTier = typeof getLegacyTier === 'function' ? getLegacyTier(legacyScore) : { name: 'Rising Star' };
  const activityTier = typeof getActivityTier === 'function' ? getActivityTier(activityPoints) : { name: 'Inactive' };
  const legacyName = legacyTier.name || legacyTier;
  const activityName = normalizeActivityTierName(activityTier);

  if (legacyName === 'GOAT') await awardUserBadge(guildId, userId, 'legacy_goat', 'GOAT Legacy', '👑', 'legacy');
  if (legacyName === 'Legend') await awardUserBadge(guildId, userId, 'legacy_legend', 'Legend Legacy', '🔥', 'legacy');
  if (legacyName === 'Elite') await awardUserBadge(guildId, userId, 'legacy_elite', 'Elite Legacy', '💎', 'legacy');
  if (activityName === 'Dedicated') await awardUserBadge(guildId, userId, 'activity_dedicated', 'Dedicated Activity', '🏹', 'activity');
  if (activityName === 'Grinder') await awardUserBadge(guildId, userId, 'activity_grinder', 'Grinder Activity', '💀', 'activity');
  if (sportsbookWins > 0) await awardUserBadge(guildId, userId, 'sportsbook_winner', 'Sportsbook Winner', '🎰', 'sportsbook');
  if (sportsbookProfit >= 10000) await awardUserBadge(guildId, userId, 'big_bettor', 'Big Bettor', '💰', 'sportsbook');
  if (championships > 0) await awardUserBadge(guildId, userId, 'champion', 'Champion', '🏆', 'legacy');

  const streamUrl = await getUserStreamUrl(guildId, userId).catch(() => null);
  if (streamUrl) await awardUserBadge(guildId, userId, 'streamer', 'Streamer', '📺', 'stream');
}

async function getUserBadges(guildId, userId, recognition = null) {
  await syncProfileBadges(guildId, userId, recognition).catch(() => null);
  const result = await pool.query(
    `SELECT * FROM user_badges WHERE guild_id = $1 AND user_id = $2 ORDER BY unlocked_at ASC LIMIT 12`,
    [guildId, userId]
  );
  return result.rows;
}

function formatAvatarLoadout(avatar) {
  return [
    'Top: ' + (avatar.equipped_top || 'Basic Tee'),
    'Bottom: ' + (avatar.equipped_bottom || 'Plain Shorts'),
    'Headwear: ' + (avatar.equipped_headwear || 'none'),
    'Accessory: ' + (avatar.equipped_accessory || 'Ghost Wristband'),
    'Footwear: ' + (avatar.equipped_footwear || 'Basic Sneakers'),
    'Pet: ' + (avatar.equipped_pet || 'none'),
    'Effect: ' + (avatar.equipped_effect || 'none'),
    'Background: ' + (avatar.equipped_background || 'Locker Room'),
  ].join('\n');
}



const VISUAL_AVATAR_SLOTS = ['headwear', 'top', 'bottom', 'accessory', 'footwear', 'pet', 'effect', 'background'];

const VISUAL_AVATAR_STARTERS = [
  { item: 'Plain Shorts', slot: 'bottom', source: 'starter' },
  { item: 'Basic Tee', slot: 'top', source: 'starter' },
  { item: 'Basic Sneakers', slot: 'footwear', source: 'starter' },
  { item: 'Ghost Wristband', slot: 'accessory', source: 'starter' },
  { item: 'Locker Room', slot: 'background', source: 'starter' },
];

function avatarColorForItem(itemName, fallback) {
  const item = String(itemName || '').toLowerCase();
  if (item.includes('ghost')) return '#f5d742';
  if (item.includes('gold')) return '#f6c343';
  if (item.includes('silver')) return '#cfd8dc';
  if (item.includes('elite')) return '#00b0ff';
  if (item.includes('crown')) return '#ffd700';
  if (item.includes('betting') || item.includes('shades')) return '#111827';
  if (item.includes('hoodie')) return '#111111';
  if (item.includes('jersey')) return '#2563eb';
  if (item.includes('championship')) return '#7c3aed';
  if (item.includes('varsity')) return '#dc2626';
  if (item.includes('basic tee')) return '#ffffff';
  if (item.includes('black')) return '#111111';
  if (item.includes('white')) return '#ffffff';
  if (item.includes('red')) return '#dc2626';
  if (item.includes('blue')) return '#2563eb';
  if (item.includes('green')) return '#16a34a';
  if (item.includes('purple')) return '#7c3aed';
  if (item.includes('pink')) return '#db2777';
  if (item.includes('orange')) return '#ea580c';
  if (item.includes('shorts')) return '#2f3542';
  if (item.includes('joggers')) return '#111827';
  if (item.includes('pants')) return '#374151';
  if (item.includes('sneakers')) return '#f8fafc';
  if (item.includes('slides')) return '#fde68a';
  return fallback;
}

async function grantVisualAvatarItem(guildId, userId, itemName, slot, source = 'unlock') {
  await pool.query(
    `INSERT INTO user_avatar_inventory (guild_id, user_id, item_name, slot, source)
     VALUES ($1, $2, $3, $4, $5)
     ON CONFLICT (guild_id, user_id, item_name)
     DO UPDATE SET slot = $4, source = COALESCE(user_avatar_inventory.source, $5)`,
    [guildId, userId, itemName, slot, source]
  );
}

async function ensureVisualAvatar(guildId, userId) {
  await pool.query(
    `INSERT INTO user_avatar (guild_id, user_id)
     VALUES ($1, $2)
     ON CONFLICT (guild_id, user_id) DO NOTHING`,
    [guildId, userId]
  );

  for (const item of VISUAL_AVATAR_STARTERS) {
    await grantVisualAvatarItem(guildId, userId, item.item, item.slot, item.source);
  }

  const result = await pool.query(
    `SELECT * FROM user_avatar WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  );

  return result.rows[0] || {
    equipped_top: 'Basic Tee',
    equipped_bottom: 'Plain Shorts',
    equipped_headwear: 'none',
    equipped_accessory: 'Ghost Wristband',
    equipped_footwear: 'Basic Sneakers',
    equipped_pet: 'none',
    equipped_effect: 'none',
    equipped_background: 'Locker Room',
  };
}

async function syncVisualAvatarUnlocks(guildId, userId, recognition = null) {
  await ensureVisualAvatar(guildId, userId);

  const row = recognition || (await pool.query(
    `SELECT * FROM user_recognition WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  )).rows[0] || {};

  const activityTier = typeof getActivityTier === 'function' ? getActivityTier(Number(row.activity_points || 0)) : { name: 'Inactive' };
  const legacyTier = typeof getLegacyTier === 'function' ? getLegacyTier(Number(row.legacy_score || 0)) : { name: 'Rising Star' };
  const activityName = typeof normalizeActivityTierName === 'function' ? normalizeActivityTierName(activityTier) : String(activityTier.name || activityTier);
  const legacyName = legacyTier.name || legacyTier;
  const sportsbookWins = Number(row.sportsbook_wins || 0);

  if (['Active', 'Dedicated', 'Grinder'].includes(activityName)) await grantVisualAvatarItem(guildId, userId, 'Ghost Wristband', 'accessory', 'activity');
  if (['Dedicated', 'Grinder'].includes(activityName)) await grantVisualAvatarItem(guildId, userId, 'Ghost Hoodie', 'top', 'activity');
  if (activityName === 'Grinder') await grantVisualAvatarItem(guildId, userId, 'Elite Sneakers', 'footwear', 'activity');

  if (['Veteran', 'Elite', 'Legend', 'GOAT'].includes(legacyName)) await grantVisualAvatarItem(guildId, userId, 'Silver Chain', 'accessory', 'legacy');
  if (['Elite', 'Legend', 'GOAT'].includes(legacyName)) await grantVisualAvatarItem(guildId, userId, 'Gold Chain', 'accessory', 'legacy');
  if (['Legend', 'GOAT'].includes(legacyName)) await grantVisualAvatarItem(guildId, userId, 'Aura Effect', 'effect', 'legacy');
  if (legacyName === 'GOAT') await grantVisualAvatarItem(guildId, userId, 'Crown', 'headwear', 'legacy');

  if (sportsbookWins >= 1) await grantVisualAvatarItem(guildId, userId, 'Betting Shades', 'headwear', 'sportsbook');
  if (sportsbookWins >= 10) await grantVisualAvatarItem(guildId, userId, 'High Roller Watch', 'accessory', 'sportsbook');

  await grantVisualAvatarItem(guildId, userId, 'Arena Tunnel', 'background', 'starter');
  await grantVisualAvatarItem(guildId, userId, 'Practice Court', 'background', 'starter');
}

async function getVisualAvatarInventory(guildId, userId) {
  await syncVisualAvatarUnlocks(guildId, userId).catch(() => null);
  const result = await pool.query(
    `SELECT * FROM user_avatar_inventory
     WHERE guild_id = $1 AND user_id = $2
     ORDER BY slot ASC, item_name ASC`,
    [guildId, userId]
  );
  return result.rows;
}

async function equipVisualAvatarItem(guildId, userId, slot, itemName) {
  const cleanSlot = String(slot || '').toLowerCase();
  if (!VISUAL_AVATAR_SLOTS.includes(cleanSlot)) {
    return { ok: false, message: 'Invalid slot. Use: ' + VISUAL_AVATAR_SLOTS.join(', ') };
  }

  await syncVisualAvatarUnlocks(guildId, userId).catch(() => null);

  const itemResult = await pool.query(
    `SELECT * FROM user_avatar_inventory
     WHERE guild_id = $1 AND user_id = $2 AND LOWER(item_name) = LOWER($3)
     LIMIT 1`,
    [guildId, userId, itemName]
  );

  if (!itemResult.rows.length) return { ok: false, message: 'You have not unlocked that cosmetic yet.' };

  const item = itemResult.rows[0];
  if (item.slot !== cleanSlot) return { ok: false, message: '**' + item.item_name + '** belongs in **' + item.slot + '**, not **' + cleanSlot + '**.' };

  const columnMap = {
    headwear: 'equipped_headwear',
    top: 'equipped_top',
    bottom: 'equipped_bottom',
    accessory: 'equipped_accessory',
    footwear: 'equipped_footwear',
    pet: 'equipped_pet',
    effect: 'equipped_effect',
    background: 'equipped_background',
  };

  await pool.query(
    `UPDATE user_avatar SET ${columnMap[cleanSlot]} = $1, updated_at = NOW()
     WHERE guild_id = $2 AND user_id = $3`,
    [item.item_name, guildId, userId]
  );

  return { ok: true, message: 'Equipped **' + item.item_name + '** to **' + cleanSlot + '**.' };
}

