function buildSetupDashboardComponents(leagueId, selectedSetting = null) {
  const settingMenu = new StringSelectMenuBuilder()
    .setCustomId('setup_select_setting:' + leagueId)
    .setPlaceholder('Choose a setting to update')
    .addOptions(SETUP_DASHBOARD_OPTIONS.map(option => ({
      label: option.label,
      value: option.value,
      description: option.description,
      default: selectedSetting === option.value,
    })));

  const panelMenu = new StringSelectMenuBuilder()
    .setCustomId('setup_create_panel:' + leagueId)
    .setPlaceholder('Create/refresh a setup panel')
    .addOptions(SETUP_PANEL_OPTIONS.map(option => ({
      label: option.label,
      value: option.value,
    })));

  const rows = [
    new ActionRowBuilder().addComponents(settingMenu),
  ];

  if (selectedSetting) {
    const kind = setupDashboardKind(selectedSetting);
    if (kind === 'role') {
      rows.push(new ActionRowBuilder().addComponents(
        new RoleSelectMenuBuilder()
          .setCustomId('setup_pick_role:' + leagueId + ':' + selectedSetting)
          .setPlaceholder('Select ' + setupDashboardLabel(selectedSetting))
          .setMinValues(1)
          .setMaxValues(1)
      ));
    } else {
      rows.push(new ActionRowBuilder().addComponents(
        new ChannelSelectMenuBuilder()
          .setCustomId('setup_pick_channel:' + leagueId + ':' + selectedSetting)
          .setPlaceholder('Select ' + setupDashboardLabel(selectedSetting))
          .setChannelTypes(ChannelType.GuildText)
          .setMinValues(1)
          .setMaxValues(1)
      ));
    }
  }

  rows.push(new ActionRowBuilder().addComponents(panelMenu));
  return rows;
}

async function refreshSetupDashboardInteraction(interaction, leagueId, selectedSetting = null, note = null) {
  const league = await getLeagueById(leagueId);
  if (!league) {
    await interaction.update({ content: 'League not found.', embeds: [], components: [] });
    return;
  }

  const embed = buildSetupDashboardEmbed(league);
  if (note) embed.setDescription(embed.data.description + '\n\n' + note);

  await interaction.update({
    embeds: [embed],
    components: buildSetupDashboardComponents(league.league_id, selectedSetting),
  });
}

async function createConfiguredPanelFromSetup(interaction, league, panelType) {
  async function requireTextChannel(channelId, fallbackChannel, label) {
    const channel = channelId ? await interaction.guild.channels.fetch(channelId).catch(() => null) : fallbackChannel;
    const botMember = await interaction.guild.members.fetchMe();
    const permissions = channel?.permissionsFor(botMember);

    if (!channel || !channel.isTextBased()) {
      return { channel: null, error: label + ' is not set or is unavailable.' };
    }

    if (!permissions?.has(PermissionFlagsBits.ViewChannel) || !permissions?.has(PermissionFlagsBits.SendMessages) || !permissions?.has(PermissionFlagsBits.EmbedLinks)) {
      return { channel: null, error: 'I need View Channel, Send Messages, and Embed Links permissions in the ' + label + '.' };
    }

    return { channel, error: null };
  }

  if (panelType === 'standings_panel') {
    const { channel, error } = await requireTextChannel(league.standings_channel_id, interaction.channel, 'standings channel');
    if (error) return error;

    const rows = await getStandingsRows(interaction.guild.id, league.league_id);
    const message = await channel.send({ embeds: [buildStandingsEmbed(league, rows)] });
    await savePanel(league, 'standings', channel.id, message.id);
    return 'Standings panel created/refreshed in ' + channel.toString() + '.';
  }

  if (panelType === 'madden_free_agents_panel') {
    if (typeof postOrRefreshMaddenFreeAgentsPanel !== 'function') return 'Madden Free Agents Board is not available in this build.';
    if (typeof ensureMaddenFreeAgencyTables === 'function') await ensureMaddenFreeAgencyTables().catch(() => null);
    const configuredChannelId = league.madden_free_agents_channel_id || await getMaddenFreeAgentsChannelId(league.league_id).catch(() => null);
    const { channel, error } = await requireTextChannel(configuredChannelId, interaction.channel, 'Madden free agents channel');
    if (error) return error + ' Set **Madden Free Agents Channel** from this setup dashboard first.';
    await setMaddenFreeAgentsChannel(league.league_id, channel.id);
    const result = await postOrRefreshMaddenFreeAgentsPanel(interaction.guild, { ...league, madden_free_agents_channel_id: channel.id }, { page: 0, position: null, minOvr: 0 });
    return result?.message || ('Madden Free Agents Board posted/refreshed in ' + channel.toString() + '.');
  }

  if (panelType === 'shop_panel') {
    const channelId = league.shop_channel_id || null;
    const { channel, error } = await requireTextChannel(channelId, interaction.channel, 'shop channel');
    if (error) return error;

    const payload = await buildPermanentShopPayload(interaction.guild.id);
    const message = await channel.send(payload);

    await pool.query(
      `DELETE FROM shop_panels WHERE guild_id = $1`,
      [interaction.guild.id]
    ).catch(() => null);

    await pool.query(
      `INSERT INTO shop_panels (guild_id, league_id, channel_id, message_id, updated_at)
       VALUES ($1, $2, $3, $4, NOW())`,
      [interaction.guild.id, league.league_id, channel.id, message.id]
    ).catch(async () => {
      await pool.query(
        `INSERT INTO shop_panels (guild_id, channel_id, message_id, updated_at)
         VALUES ($1, $2, $3, NOW())`,
        [interaction.guild.id, channel.id, message.id]
      ).catch(() => null);
    });

    return 'Shop panel created/refreshed in ' + channel.toString() + '.';
  }

  if (panelType === 'sportsbook_panel') {
    const { channel, error } = await requireTextChannel(league.sportsbook_channel_id, interaction.channel, 'sportsbook channel');
    if (error) return error;

    const openSportsbookResult = await pool.query(
      `SELECT * FROM sportsbook_games WHERE guild_id = $1 AND status = 'open' ORDER BY created_at DESC LIMIT 5`,
      [interaction.guild.id]
    );

    const message = await channel.send({
      embeds: [await buildSportsbookPanelEmbed(interaction.guild.id)],
      components: buildSportsbookBetBoardButtons(openSportsbookResult.rows),
    });

    await saveSportsbookPanel(interaction.guild.id, channel.id, message.id);
    return 'Sportsbook board created/refreshed in ' + channel.toString() + '.';
  }

  if (panelType === 'team_owners_panel') {
    const { channel, error } = await requireTextChannel(league.team_owners_channel_id, interaction.channel, 'team owners channel');
    if (error) return error;
    await channel.send({ embeds: [await buildTeamOwnersEmbed(interaction.guild, league)] });
    return 'Team Owners panel posted in ' + channel.toString() + '.';
  }

  if (panelType === 'trade_count_panel') {
    const { channel, error } = await requireTextChannel(league.trade_count_channel_id, interaction.channel, 'trade count channel');
    if (error) return error;
    await channel.send({ embeds: [await buildTradeCountEmbed(league)] });
    return 'Trade Count panel posted in ' + channel.toString() + '.';
  }

  if (panelType === 'trade_offer_panel') {
    const { channel, error } = await requireTextChannel(league.trade_offer_channel_id, interaction.channel, 'trade offer channel');
    if (error) return error;

    if (typeof buildTradeOfferPanel === 'function') {
      await channel.send(buildTradeOfferPanel(league));
      return 'Trade Offer panel posted in ' + channel.toString() + '.';
    }

    const embed = new EmbedBuilder()
      .setTitle('Offer a Trade')
      .setDescription('Use this channel to start and manage trade offers.')
      .setColor(0x57F287)
      .setFooter({ text: 'GG Sports • Trade Offers' })
      .setTimestamp();

    await channel.send({ embeds: [embed] });
    return 'Basic Trade Offer panel posted in ' + channel.toString() + '.';
  }

  if (panelType === 'ticket_panel') {
    const channelId = league.setup_ticket_channel_id || league.setup_support_channel_id;
    const { channel, error } = await requireTextChannel(channelId, interaction.channel, 'ticket/support channel');
    if (error) return error;

    const embed = new EmbedBuilder()
      .setTitle('Support Tickets')
      .setDescription('Use /ticket open, /ticket dispute, or /ticket game to create a ticket.')
      .setColor(0x5865F2)
      .setFooter({ text: 'GG Sports • Tickets' })
      .setTimestamp();

    await channel.send({ embeds: [embed] });
    return 'Ticket panel posted in ' + channel.toString() + '.';
  }

  return 'Unknown panel type.';
}







function maddenWeekSortValue(weekLabel) {
  const label = String(weekLabel || '').toLowerCase();
  const n = Number((label.match(/\d+/) || [999])[0]);
  if (label.includes('preseason')) return n - 100;
  if (label.includes('wildcard')) return 100;
  if (label.includes('divisional')) return 101;
  if (label.includes('conference')) return 102;
  if (label.includes('super bowl')) return 103;
  if (label.includes('week')) return n;
  return 999;
}


function normalizeMaddenWeekFilterInput(week) {
  if (!week) return null;
  const value = String(week).trim();
  if (!value) return null;

  const compact = value.toLowerCase().replace(/\s+/g, '');
  const numberOnly = compact.match(/^\d+$/);
  if (numberOnly) return 'Week ' + value;

  const weekNumber = compact.match(/^week(\d+)$/);
  if (weekNumber) return 'Week ' + weekNumber[1];

  const preseasonNumber = compact.match(/^preseason(?:week)?(\d+)$/);
  if (preseasonNumber) return 'Preseason Week ' + preseasonNumber[1];

  return value.replace(/^week\s*(\d+)$/i, 'Week $1').replace(/^preseason\s*week\s*(\d+)$/i, 'Preseason Week $1');
}

function isPlaceholderZeroZero(game) {
  const status = String(game?.status || '').toLowerCase();
  const away = Number(game?.away_score ?? 0);
  const home = Number(game?.home_score ?? 0);
  return away === 0 && home === 0 && status !== 'completed_with_real_score';
}


function formatMaddenGameScore(game) {
  const away = game.away_score;
  const home = game.home_score;
  const hasScore = away !== null && away !== undefined && home !== null && home !== undefined;
  if (!hasScore) return '';

  const awayNum = Number(away);
  const homeNum = Number(home);
  const realScore = awayNum !== 0 || homeNum !== 0 || String(game.status || '').toLowerCase() === 'completed_with_real_score';
  if (!realScore) return '';

  return ' • ' + away + '-' + home;
}

function formatMaddenTeamGameLine(teamName, game) {
  const isHome = String(game.home_team || '').toLowerCase() === String(teamName || '').toLowerCase();
  const opp = isHome ? game.away_team : game.home_team;
  const scoreInfo = resolveMaddenScoresFromRawGameDeep(game);
  const resolvedHomeScore = scoreInfo.homeScore ?? game.home_score;
  const resolvedAwayScore = scoreInfo.awayScore ?? game.away_score;
  const teamScore = isHome ? resolvedHomeScore : resolvedAwayScore;
  const oppScore = isHome ? resolvedAwayScore : resolvedHomeScore;
  const status = String(game.status || 'scheduled').toLowerCase();

  let result;
  if (status === 'completed_with_real_score' || ((status === 'completed' || status === 'final') && (Number(teamScore) !== 0 || Number(oppScore) !== 0))) {
    result = Number(teamScore) > Number(oppScore)
      ? 'W ' + teamScore + '-' + oppScore
      : Number(teamScore) < Number(oppScore)
        ? 'L ' + teamScore + '-' + oppScore
        : 'T ' + teamScore + '-' + oppScore;
  } else if (status === 'completed' || status === 'final') {
    const winner = resolveMaddenWinnerFromRawGame(game, game.home_team, game.away_team);
    if (winner === 'tie') result = 'T';
    else if ((isHome && winner === 'home') || (!isHome && winner === 'away')) result = 'W';
    else if ((isHome && winner === 'away') || (!isHome && winner === 'home')) result = 'L';
    else result = 'completed';
  } else {
    result = 'scheduled';
  }

  return '**' + (game.week_label || 'Week TBD') + '** ' + (isHome ? 'vs ' : '@ ') + opp + ' — ' + result;
}


function getMaddenDivisionSortRank(divisionName) {
  const order = [
    'AFC East', 'AFC North', 'AFC South', 'AFC West',
    'NFC East', 'NFC North', 'NFC South', 'NFC West',
  ];
  const idx = order.findIndex(item => item.toLowerCase() === String(divisionName || '').toLowerCase());
  return idx === -1 ? 999 : idx;
}

function getMaddenConferenceSortRank(conferenceName) {
  const conf = String(conferenceName || '').toUpperCase();
  if (conf === 'AFC') return 1;
  if (conf === 'NFC') return 2;
  return 999;
}

function inferMaddenConferenceFromDivision(divisionName) {
  const div = String(divisionName || '');
  if (/^AFC/i.test(div)) return 'AFC';
  if (/^NFC/i.test(div)) return 'NFC';
  return 'League';
}

function getMaddenDivisionForTeam(teamName) {
  const name = String(teamName || '').toLowerCase();
  const map = {
    'bills': 'AFC East',
    'dolphins': 'AFC East',
    'patriots': 'AFC East',
    'jets': 'AFC East',

    'ravens': 'AFC North',
    'bengals': 'AFC North',
    'browns': 'AFC North',
    'steelers': 'AFC North',

    'texans': 'AFC South',
    'colts': 'AFC South',
    'jaguars': 'AFC South',
    'titans': 'AFC South',

    'broncos': 'AFC West',
    'chiefs': 'AFC West',
    'raiders': 'AFC West',
    'chargers': 'AFC West',

    'cowboys': 'NFC East',
    'giants': 'NFC East',
    'eagles': 'NFC East',
    'commanders': 'NFC East',

    'bears': 'NFC North',
    'lions': 'NFC North',
    'packers': 'NFC North',
    'vikings': 'NFC North',

    'falcons': 'NFC South',
    'panthers': 'NFC South',
    'saints': 'NFC South',
    'buccaneers': 'NFC South',

    'cardinals': 'NFC West',
    'rams': 'NFC West',
    '49ers': 'NFC West',
    'seahawks': 'NFC West',
  };

  for (const [key, division] of Object.entries(map)) {
    if (name === key || name.includes(key)) return division;
  }

  return 'League';
}

function getMaddenConferenceForTeam(teamName) {
  return inferMaddenConferenceFromDivision(getMaddenDivisionForTeam(teamName));
}


function formatMaddenStandingsRecord(team) {
  const wins = Number(team.wins || 0);
  const losses = Number(team.losses || 0);
  const ties = Number(team.ties || 0);
  return ties ? `${wins}-${losses}-${ties}` : `${wins}-${losses}`;
}

function sortMaddenStandingRows(rows) {
  return [...(rows || [])].sort((a, b) =>
    Number(b.wins || 0) - Number(a.wins || 0) ||
    Number(a.losses || 0) - Number(b.losses || 0) ||
    (Number(b.points_for || 0) - Number(b.points_against || 0)) - (Number(a.points_for || 0) - Number(a.points_against || 0)) ||
    Number(b.points_for || 0) - Number(a.points_for || 0) ||
    String(a.team_name || '').localeCompare(String(b.team_name || ''))
  );
}

function formatMaddenStandingLine(team, index) {
  const pf = Number(team.points_for || 0);
  const pa = Number(team.points_against || 0);
  const diff = pf - pa;
  const seed = team.seed ? `${team.seed}. ` : `${index + 1}. `;
  const rank = team.rank ? ` • Rank #${team.rank}` : '';
  return `**${seed}${team.team_name}** — ${formatMaddenStandingsRecord(team)} • PF ${pf} • PA ${pa} • DIFF ${diff >= 0 ? '+' : ''}${diff}${rank}`;
}


function formatMaddenPowerMovement(row) {
  const currentRank = Number(row.rank || 0);
  const previousRank = row.previous_rank == null ? null : Number(row.previous_rank || 0);
  if (!previousRank || !currentRank) return 'NEW';
  const movement = previousRank - currentRank;
  if (movement > 0) return '▲ +' + movement;
  if (movement < 0) return '▼ ' + movement;
  return '—';
}

function formatMaddenPowerScore(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n)) return '0';
  return n.toFixed(1).replace(/\.0$/, '');
}

async function recalculateMaddenPowerRankings(guildId, leagueId) {
  const previousResult = await pool.query(
    `SELECT team_name, rank
     FROM madden_power_rankings
     WHERE league_id::text = $1::text`,
    [leagueId]
  );
  const previousRanks = new Map(previousResult.rows.map(row => [String(row.team_name || '').toLowerCase(), Number(row.rank || 0)]));

  const result = await pool.query(
    `WITH base AS (
       SELECT
         team_name,
         wins,
         losses,
         ties,
         points_for,
         points_against,
         GREATEST((wins + losses + ties), 1) AS games_played
       FROM madden_imported_team_stats
       WHERE guild_id = $1::text
         AND league_id::text = $2::text
     ), ranked AS (
       SELECT
         *,
         (points_for - points_against) AS point_diff,
         DENSE_RANK() OVER (ORDER BY (points_for::numeric / games_played::numeric) DESC) AS offense_rank,
         DENSE_RANK() OVER (ORDER BY (points_against::numeric / games_played::numeric) ASC) AS defense_rank
       FROM base
     ), scored AS (
       SELECT
         *,
         ((wins * 100)
          + ((points_for - points_against) * 3)
          + ((33 - offense_rank) * 5)
          + ((33 - defense_rank) * 5))::numeric AS power_score
       FROM ranked
     )
     SELECT *
     FROM scored
     ORDER BY power_score DESC, wins DESC, losses ASC, point_diff DESC, points_for DESC, team_name ASC`,
    [guildId, leagueId]
  );

  const rankings = result.rows.map((row, index) => ({
    ...row,
    rank: index + 1,
    previous_rank: previousRanks.get(String(row.team_name || '').toLowerCase()) || null,
  }));

  for (const row of rankings) {
    await pool.query(
      `INSERT INTO madden_power_rankings (league_id, team_name, rank, previous_rank, power_score, updated_at)
       VALUES ($1, $2, $3, $4, $5, NOW())
       ON CONFLICT (league_id, team_name)
       DO UPDATE SET
         rank = EXCLUDED.rank,
         previous_rank = EXCLUDED.previous_rank,
         power_score = EXCLUDED.power_score,
         updated_at = NOW()`,
      [leagueId, row.team_name, row.rank, row.previous_rank, row.power_score]
    );
  }

  return rankings;
}

function buildMaddenPowerRankingsEmbed(league, rankings) {
  const NL = String.fromCharCode(10);

  if (!rankings?.length) {
    return new EmbedBuilder()
      .setTitle('🏆 Madden Power Rankings • ' + league.league_name)
      .setColor(0xFEE75C)
      .setDescription('No imported Madden team stats found yet. Run `/madden sync` first, then try `/madden powerrankings`.')
      .setFooter({ text: 'GG Sports • 7J-7ZQ-R Power Rankings' })
      .setTimestamp();
  }

  const lines = rankings.map(row => {
    const wins = Number(row.wins || 0);
    const losses = Number(row.losses || 0);
    const ties = Number(row.ties || 0);
    const record = ties ? `${wins}-${losses}-${ties}` : `${wins}-${losses}`;
    const diff = Number(row.point_diff || 0);
    const diffText = diff >= 0 ? '+' + diff : String(diff);
    return `**${row.rank}. ${row.team_name}** (${record}) — ${formatMaddenPowerMovement(row)}\nScore ${formatMaddenPowerScore(row.power_score)} • DIFF ${diffText} • OFF #${row.offense_rank || 'N/A'} • DEF #${row.defense_rank || 'N/A'}`;
  });

  return new EmbedBuilder()
    .setTitle('🏆 Madden Power Rankings • ' + league.league_name)
    .setColor(0xFEE75C)
    .setDescription(lines.join(NL + NL).slice(0, 4096))
    .setFooter({ text: 'GG Sports • 7J-7ZQ-R Power Rankings' })
    .setTimestamp();
}


function maddenTeamNameMatches(candidate, target) {
  const c = String(candidate || '').trim().toLowerCase();
  const t = String(target || '').trim().toLowerCase();
  if (!c || !t) return false;
  const cAbbr = String(getMaddenTeamAbbrev(candidate) || '').trim().toLowerCase();
  const tAbbr = String(getMaddenTeamAbbrev(target) || '').trim().toLowerCase();
  return c === t || (!!cAbbr && cAbbr === t) || (!!tAbbr && c === tAbbr) || (!!cAbbr && !!tAbbr && cAbbr === tAbbr);
}

function maddenRecordWinPct(row) {
  const wins = Number(row?.wins || 0);
  const losses = Number(row?.losses || 0);
  const ties = Number(row?.ties || 0);
  const games = wins + losses + ties;
  return games > 0 ? (wins + (ties * 0.5)) / games : 0;
}

function maddenTeamGamesPlayed(row) {
  return Math.max(1, Number(row?.wins || 0) + Number(row?.losses || 0) + Number(row?.ties || 0));
}

function formatMaddenOneDecimal(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n)) return '0.0';
  return n.toFixed(1);
}

async function getMaddenImportedTeamRow(guildId, leagueId, teamName) {
  const result = await pool.query(
    `SELECT *
     FROM madden_imported_team_stats
     WHERE guild_id = $1::text
       AND league_id::text = $2::text
       AND (
         LOWER(team_name) = LOWER($3)
         OR LOWER(team_name) = LOWER($4)
       )
     LIMIT 1`,
    [guildId, leagueId, teamName, getMaddenTeamAbbrev(teamName)]
  );
  return result.rows?.[0] || null;
}

async function getMaddenTeamSeasonLeader(guildId, leagueId, teamName, categoryKey) {
  const result = await getMaddenLeagueLeaders(guildId, leagueId, categoryKey, null, 250).catch(() => ({ rows: [] }));
  return (result.rows || []).find(row => maddenTeamNameMatches(row.resolved_team_name || row.stat_team_name || row.team_name, teamName)) || null;
}

function formatMaddenMatchupLeader(row, statLabel = 'Yards', fallback = 'No data') {
  if (!row) return fallback;
  const team = getMaddenTeamAbbrev(row.resolved_team_name || row.stat_team_name || row.team_name);
  const position = row.position ? String(row.position).toUpperCase() : '';
  const meta = [team, position].filter(Boolean).join('\n');
  const value = row.leader_value != null ? formatMaddenLeaderNumber(row.leader_value) + ' ' + statLabel : 'No stat';
  return `**${row.player_name || 'Unknown'}**${meta ? ` (${meta})` : ''}\n${value}`;
}

