function maddenJsonNumberSql(key) {
  const safeKey = String(key || '').replace(/[^A-Za-z0-9_]/g, '');
  return `CASE WHEN raw_payload->>'${safeKey}' ~ '^-?[0-9]+(\\\\.[0-9]+)?$' THEN (raw_payload->>'${safeKey}')::numeric ELSE 0 END`;
}


const NFL_TEAM_ABBREVIATIONS = {
  '49ers': 'SF', bears: 'CHI', bengals: 'CIN', bills: 'BUF', broncos: 'DEN', browns: 'CLE',
  buccaneers: 'TB', cardinals: 'ARI', chargers: 'LAC', chiefs: 'KC', colts: 'IND', commanders: 'WAS',
  cowboys: 'DAL', dolphins: 'MIA', eagles: 'PHI', falcons: 'ATL', giants: 'NYG', jaguars: 'JAX',
  jets: 'NYJ', lions: 'DET', packers: 'GB', panthers: 'CAR', patriots: 'NE', raiders: 'LV',
  rams: 'LAR', ravens: 'BAL', saints: 'NO', seahawks: 'SEA', steelers: 'PIT', texans: 'HOU',
  titans: 'TEN', vikings: 'MIN',
};

function getMaddenTeamAbbrev(teamName) {
  const key = String(teamName || '').trim().toLowerCase();
  if (!key) return '';
  if (key.length <= 4 && key === key.toUpperCase?.()) return key;
  return NFL_TEAM_ABBREVIATIONS[key] || String(teamName).trim();
}

function maddenTeamDisplayName(teamName, options = {}) {
  const clean = String(teamName || '').trim();
  if (!clean) return options.fallback || 'FA';
  const abbr = getMaddenTeamAbbrev(clean);
  if (!abbr || abbr === clean) return clean;
  return `${clean} (${abbr})`;
}

function getMaddenRankMedal(index) {
  if (index === 0) return '🥇';
  if (index === 1) return '🥈';
  if (index === 2) return '🥉';
  return `**${index + 1}.**`;
}

function maddenCompactStatLine(line) {
  return String(line || '').replaceAll(' • ', ' | ');
}

const MADDEN_AWARD_RACES = {
  mvp: { title: 'MVP Race', emoji: '🏆', type: 'overall' },
  opoy: { title: 'Offensive Player of the Year Race', emoji: '⚡', type: 'offense' },
  dpoy: { title: 'Defensive Player of the Year Race', emoji: '🛡️', type: 'defense' },
  oroy: { title: 'Offensive Rookie of the Year Race', emoji: '🌟', type: 'offense_rookie' },
  droy: { title: 'Defensive Rookie of the Year Race', emoji: '🔒', type: 'defense_rookie' },
};

function maddenAwardPlayerKey(row) {
  return String(row?.roster_id || row?.grouping_key || `${row?.player_name || 'Unknown'}:${row?.resolved_team_name || row?.stat_team_name || ''}`).toLowerCase();
}

function mergeMaddenAwardRow(map, row) {
  const key = maddenAwardPlayerKey(row);
  const current = map.get(key) || {
    player_name: row.player_name || 'Unknown Player',
    team_name: row.resolved_team_name || row.stat_team_name || '',
    position: row.position || '',
    age: row.age == null ? null : Number(row.age),
    passYds: 0, passTDs: 0, passInts: 0,
    rushYds: 0, rushTDs: 0,
    recYds: 0, recTDs: 0, recCatches: 0,
    defTotalTackles: 0, defSacks: 0, defInts: 0, defForcedFum: 0, defDeflections: 0, defTDs: 0,
    is_rookie: false,
    roster_raw_payload: row.roster_raw_payload_text || row.roster_raw_payload || row.raw_payload || null,
  };

  current.player_name = current.player_name || row.player_name || 'Unknown Player';
  current.team_name = current.team_name || row.resolved_team_name || row.stat_team_name || '';
  current.position = current.position || row.position || '';
  if (current.age == null && row.age != null) current.age = Number(row.age);
  if (!current.roster_raw_payload && (row.roster_raw_payload_text || row.roster_raw_payload || row.raw_payload)) current.roster_raw_payload = row.roster_raw_payload_text || row.roster_raw_payload || row.raw_payload;
  current.is_rookie = current.is_rookie || isMaddenRawPayloadRookie(current.roster_raw_payload);

  // 7J-9B-D: Award races may pull multiple leader categories from the same stat type
  // (ex: passing + passing_tds both contain passYds/passTDs/passInts). These rows are
  // season-total snapshots, not separate stat events, so adding them double-counts.
  // Keep the highest season snapshot per field instead.
  for (const field of ['passYds','passTDs','passInts','rushYds','rushTDs','recYds','recTDs','recCatches','defTotalTackles','defSacks','defInts','defForcedFum','defDeflections','defTDs']) {
    current[field] = Math.max(Number(current[field] || 0), Number(row[field] || 0));
  }

  map.set(key, current);
}

function isMaddenOffensivePosition(position) {
  return ['QB', 'HB', 'RB', 'FB', 'WR', 'TE'].includes(String(position || '').toUpperCase());
}

function isMaddenDefensivePosition(position) {
  return ['DE', 'LE', 'RE', 'DT', 'LOLB', 'ROLB', 'MLB', 'LB', 'CB', 'FS', 'SS', 'S'].includes(String(position || '').toUpperCase());
}

function parseMaddenJsonMaybe(value) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  try { return JSON.parse(String(value)); } catch { return null; }
}

function findMaddenRawValueByKey(raw, wantedKeys) {
  const seen = new Set();
  const stack = [raw];
  const wanted = new Set(wantedKeys.map(k => String(k).toLowerCase()));
  while (stack.length) {
    const item = stack.pop();
    if (!item || typeof item !== 'object') continue;
    if (seen.has(item)) continue;
    seen.add(item);
    if (Array.isArray(item)) {
      for (const child of item) stack.push(child);
      continue;
    }
    for (const [key, value] of Object.entries(item)) {
      const normalizedKey = String(key).toLowerCase();
      if (wanted.has(normalizedKey)) return value;
      if (value && typeof value === 'object') stack.push(value);
    }
  }
  return null;
}

function booleanishMaddenRookieValue(value) {
  if (value === true) return true;
  if (value === false) return false;
  const text = String(value ?? '').trim().toLowerCase();
  if (['true', 'yes', 'y', 'rookie'].includes(text)) return true;
  if (['false', 'no', 'n', 'veteran'].includes(text)) return false;
  const number = Number(text);
  if (Number.isFinite(number)) return number === 1;
  return null;
}

function isMaddenRawPayloadRookie(rawPayload) {
  const raw = parseMaddenJsonMaybe(rawPayload);
  if (!raw) return false;

  const explicitRookie = findMaddenRawValueByKey(raw, [
    'isRookie', 'rookie', 'rookieFlag', 'is_rookie', 'isRookieFlag'
  ]);
  const explicit = booleanishMaddenRookieValue(explicitRookie);
  if (explicit === true) return true;
  if (explicit === false) return false;

  const yearsValue = findMaddenRawValueByKey(raw, [
    'yearsPro', 'yrsPro', 'proYears', 'yearsInLeague', 'nflYears', 'experience', 'exp', 'playerExperience'
  ]);
  if (yearsValue != null && yearsValue !== '') {
    const years = Number(String(yearsValue).replace(/[^0-9.-]/g, ''));
    if (Number.isFinite(years)) return years === 0;
  }

  return false;
}

function getMaddenYearsProValue(player) {
  const directNames = ['yearsPro', 'yearspro', 'years_pro', 'yrsPro', 'yrspro', 'yrs_pro', 'proYears', 'proyears', 'pro_years', 'yearsInLeague', 'yearsinleague', 'nflYears', 'nflyears', 'experience', 'exp'];
  for (const name of directNames) {
    if (player && Object.prototype.hasOwnProperty.call(player, name)) {
      const n = Number(String(player[name]).replace(/[^0-9.-]/g, ''));
      if (Number.isFinite(n)) return n;
    }
  }
  const raw = parseMaddenJsonMaybe(player?.roster_raw_payload || player?.raw_payload || player?.roster_raw_payload_text);
  const rawValue = findMaddenRawValueByKey(raw, directNames);
  if (rawValue != null && rawValue !== '') {
    const n = Number(String(rawValue).replace(/[^0-9.-]/g, ''));
    if (Number.isFinite(n)) return n;
  }
  return null;
}

function isMaddenRookieCandidate(player) {
  const yearsPro = getMaddenYearsProValue(player);
  if (yearsPro != null) return yearsPro === 0;
  return player.is_rookie === true || isMaddenRawPayloadRookie(player.roster_raw_payload || player.raw_payload || player.roster_raw_payload_text);
}


function collectMaddenRookieProbeFields(rawPayload) {
  const raw = parseMaddenJsonMaybe(rawPayload);
  if (!raw || typeof raw !== 'object') return { matches: [], topLevelKeys: [] };

  const matches = [];
  const topLevelKeys = Array.isArray(raw) ? [] : Object.keys(raw).slice(0, 30);
  const seen = new Set();
  const stack = [{ value: raw, path: '' }];
  const keyPattern = /(rook|exp|year|yrs|pro|draft|season|service|league|contract)/i;

  while (stack.length && matches.length < 40) {
    const { value, path } = stack.pop();
    if (!value || typeof value !== 'object') continue;
    if (seen.has(value)) continue;
    seen.add(value);

    if (Array.isArray(value)) {
      for (let i = 0; i < Math.min(value.length, 20); i++) stack.push({ value: value[i], path: `${path}[${i}]` });
      continue;
    }

    for (const [key, child] of Object.entries(value)) {
      const childPath = path ? `${path}.${key}` : key;
      if (keyPattern.test(key)) {
        const displayValue = child && typeof child === 'object'
          ? (Array.isArray(child) ? `[Array ${child.length}]` : '[Object]')
          : String(child ?? 'null');
        matches.push({ path: childPath, value: displayValue.slice(0, 90) });
      }
      if (child && typeof child === 'object') stack.push({ value: child, path: childPath });
    }
  }

  return { matches, topLevelKeys };
}

function formatMaddenRookieProbeRow(row, index) {
  const probe = collectMaddenRookieProbeFields(row.raw_payload_text || row.raw_payload);
  const header = `**${index + 1}. ${row.player_name || row.full_name || 'Unknown'}** — ${row.team_name || 'FA'} ${row.position || ''}${row.age != null ? ` • Age ${row.age}` : ''}`;
  const keyLines = probe.matches.length
    ? probe.matches.slice(0, 12).map(item => `\`${item.path}\`: ${item.value}`).join('\n')
    : 'No rookie/experience-style keys found in this raw payload.';
  const topKeys = probe.topLevelKeys.length ? `\nTop keys: ${probe.topLevelKeys.slice(0, 12).map(k => `\`${k}\``).join(', ')}` : '';
  return `${header}\n${keyLines}${topKeys}`;
}

async function buildMaddenRookieDataProbeEmbed(guildId, leagueId, league, playerName) {
  await ensureMaddenPlayerPersistenceTables();
  const search = `%${String(playerName || '').trim()}%`;
  const rows = [];

  const primary = await pool.query(
    `SELECT 'madden_players' AS source_table, full_name AS player_name, team_name, position, age, roster_id, presentation_id, raw_payload::text AS raw_payload_text
     FROM madden_players
     WHERE guild_id = $1 AND league_id = $2 AND LOWER(full_name) LIKE LOWER($3)
     ORDER BY imported_at DESC
     LIMIT 5`,
    [guildId, leagueId, search]
  ).catch(() => ({ rows: [] }));
  rows.push(...(primary.rows || []));

  const imported = await pool.query(
    `SELECT 'madden_imported_players' AS source_table, player_name, team_name, position, overall, raw_payload::text AS raw_payload_text
     FROM madden_imported_players
     WHERE guild_id = $1 AND league_id = $2 AND LOWER(player_name) LIKE LOWER($3)
     ORDER BY imported_at DESC
     LIMIT 5`,
    [guildId, leagueId, search]
  ).catch(() => ({ rows: [] }));
  rows.push(...(imported.rows || []));

  const statRows = await pool.query(
    `SELECT 'madden_player_weekly_stats' AS source_table, full_name AS player_name, team_name, position, raw_payload::text AS raw_payload_text
     FROM madden_player_weekly_stats
     WHERE guild_id = $1 AND league_id = $2 AND LOWER(full_name) LIKE LOWER($3)
     ORDER BY imported_at DESC
     LIMIT 3`,
    [guildId, leagueId, search]
  ).catch(() => ({ rows: [] }));
  rows.push(...(statRows.rows || []));

  const description = rows.length
    ? rows.slice(0, 6).map(formatMaddenRookieProbeRow).join('\n\n').slice(0, 3900)
    : `No imported player rows found matching \`${String(playerName || '').slice(0, 80)}\`. Try the exact player name from \`/madden player\`.`;

  return new EmbedBuilder()
    .setTitle(`🔎 Madden Rookie Data Probe • ${league?.league_name || 'Madden League'}`)
    .setDescription(description)
    .setColor(0xFEE75C)
    .setFooter({ text: 'GG Sports • 7J-7ZR-D Rookie/Draft Fix' })
    .setTimestamp();
}

function scoreMaddenAwardCandidate(player, type) {
  const passScore = (Number(player.passYds || 0) * 0.05) + (Number(player.passTDs || 0) * 25) - (Number(player.passInts || 0) * 10);
  const rushScore = (Number(player.rushYds || 0) * 0.08) + (Number(player.rushTDs || 0) * 30);
  const recScore = (Number(player.recYds || 0) * 0.08) + (Number(player.recTDs || 0) * 30) + (Number(player.recCatches || 0) * 1.5);
  const defScore = (Number(player.defTotalTackles || 0) * 2) + (Number(player.defSacks || 0) * 25) + (Number(player.defInts || 0) * 30) + (Number(player.defForcedFum || 0) * 20) + (Number(player.defDeflections || 0) * 4) + (Number(player.defTDs || 0) * 35);

  if (type === 'defense' || type === 'defense_rookie') return defScore;
  if (type === 'offense' || type === 'offense_rookie') return passScore + rushScore + recScore;
  return passScore + rushScore + recScore + (defScore * 0.8);
}

function formatMaddenAwardStatLine(player, type) {
  if (type === 'defense' || type === 'defense_rookie') {
    return `${formatMaddenLeaderNumber(player.defTotalTackles)} TKL | ${formatMaddenLeaderNumber(player.defSacks)} SACK | ${formatMaddenLeaderNumber(player.defInts)} INT | ${formatMaddenLeaderNumber(player.defForcedFum)} FF`;
  }

  const pos = String(player.position || '').toUpperCase();
  if (pos === 'QB' || Number(player.passYds || 0) >= Number(player.rushYds || 0) + Number(player.recYds || 0)) {
    return `${formatMaddenLeaderNumber(player.passYds)} YDS | ${formatMaddenLeaderNumber(player.passTDs)} TD | ${formatMaddenLeaderNumber(player.passInts)} INT`;
  }
  if (Number(player.rushYds || 0) >= Number(player.recYds || 0)) {
    return `${formatMaddenLeaderNumber(player.rushYds)} RUSH YDS | ${formatMaddenLeaderNumber(player.rushTDs)} TD | ${formatMaddenLeaderNumber(player.recYds)} REC YDS`;
  }
  return `${formatMaddenLeaderNumber(player.recYds)} REC YDS | ${formatMaddenLeaderNumber(player.recTDs)} TD | ${formatMaddenLeaderNumber(player.recCatches)} REC`;
}

async function getMaddenAwardsRace(guildId, leagueId, awardKey, limit = 5) {
  const race = MADDEN_AWARD_RACES[awardKey] || MADDEN_AWARD_RACES.mvp;
  const map = new Map();

  const categories = race.type === 'defense' || race.type === 'defense_rookie'
    ? ['tackles', 'sacks', 'interceptions', 'forced_fumbles', 'pass_deflections']
    : ['passing', 'rushing', 'receiving', 'passing_tds', 'rushing_tds', 'receiving_tds'];

  for (const categoryKey of categories) {
    const data = await getMaddenLeagueLeaders(guildId, leagueId, categoryKey, null, 75).catch(() => ({ rows: [] }));
    for (const row of data.rows || []) mergeMaddenAwardRow(map, row);
  }

  let players = Array.from(map.values())
    .filter(player => {
      if (race.type === 'defense' || race.type === 'defense_rookie') return isMaddenDefensivePosition(player.position) || scoreMaddenAwardCandidate(player, race.type) > 0;
      if (race.type === 'offense' || race.type === 'offense_rookie') return isMaddenOffensivePosition(player.position) || scoreMaddenAwardCandidate(player, race.type) > 0;
      return scoreMaddenAwardCandidate(player, race.type) > 0;
    });

  if (race.type.endsWith('_rookie')) {
    players = players.filter(isMaddenRookieCandidate);
  }

  return players
    .map(player => ({ ...player, award_score: scoreMaddenAwardCandidate(player, race.type) }))
    .filter(player => player.award_score > 0)
    .sort((a, b) => b.award_score - a.award_score || String(a.player_name).localeCompare(String(b.player_name)))
    .slice(0, limit);
}

function buildMaddenAwardsRaceEmbed(league, awardKey, rows) {
  const race = MADDEN_AWARD_RACES[awardKey] || MADDEN_AWARD_RACES.mvp;
  const lines = rows.length
    ? rows.map((player, index) => {
        const medal = getMaddenRankMedal(index);
        const team = getMaddenTeamAbbrev(player.team_name);
        const label = [team, String(player.position || '').toUpperCase()].filter(Boolean).join('\n');
        const rookieText = race.type.endsWith('_rookie') ? ' | Rookie' : '';
        return `${medal} **${player.player_name}**${label ? `
${label}` : ''}
${formatMaddenAwardStatLine(player, race.type)}${rookieText}`;
      }).join('\n\n')
    : (race.type.endsWith('_rookie')
        ? 'No rookie stat rows found for this award race yet. This command now requires a real rookie flag or 0 years pro from the imported EA roster data.'
        : 'No imported stat rows found for this award race yet. Run `/madden sync` after games have been played.');

  return new EmbedBuilder()
    .setTitle(`${race.emoji} Madden ${race.title} • ${league.league_name || 'Madden League'}`)
    .setColor(0xFEE75C)
    .setDescription(lines.slice(0, 3900))
    .setFooter({ text: 'GG Sports • 7J-9B-J Zero-Score Game Cleanup' })
    .setTimestamp();
}


function maddenNewsTeamRecordText(row) {
  if (!row) return '';
  return formatMaddenStandingsRecord(row);
}

function maddenNewsHasRealScore(game) {
  const homeRaw = game?.home_score;
  const awayRaw = game?.away_score;
  if (homeRaw === null || homeRaw === undefined || awayRaw === null || awayRaw === undefined) return false;
  const homeScore = Number(homeRaw);
  const awayScore = Number(awayRaw);
  if (!Number.isFinite(homeScore) || !Number.isFinite(awayScore)) return false;
  // Imported EA schedules can sometimes carry 0-0 placeholders. Do not report those as completed results.
  if (homeScore === 0 && awayScore === 0) return false;
  return true;
}

function maddenNewsGameHeadline(game, teamRowsByName) {
  const home = String(game.home_team || 'Home');
  const away = String(game.away_team || 'Away');
  const homeScore = Number(game.home_score);
  const awayScore = Number(game.away_score);

  if (!maddenNewsHasRealScore(game)) {
    const homeRow = teamRowsByName.get(home.toLowerCase());
    const awayRow = teamRowsByName.get(away.toLowerCase());
    const homeRecord = maddenNewsTeamRecordText(homeRow);
    const awayRecord = maddenNewsTeamRecordText(awayRow);
    if (homeRow && Number(homeRow.wins || 0) >= 2 && Number(homeRow.losses || 0) === 0) return `⚡ ${home} improves to ${homeRecord}`;
    if (awayRow && Number(awayRow.wins || 0) >= 2 && Number(awayRow.losses || 0) === 0) return `⚡ ${away} improves to ${awayRecord}`;
    if (homeRecord || awayRecord) return `⚡ ${away} at ${home} headlines the week${homeRecord ? ` with ${home} sitting at ${homeRecord}` : ''}${awayRecord ? ` and ${away} at ${awayRecord}` : ''}`;
    return null;
  }

  const winner = homeScore >= awayScore ? home : away;
  const loser = homeScore >= awayScore ? away : home;
  const winnerScore = homeScore >= awayScore ? homeScore : awayScore;
  const loserScore = homeScore >= awayScore ? awayScore : homeScore;
  const margin = winnerScore - loserScore;
  const winnerRow = teamRowsByName.get(String(winner).toLowerCase());
  const loserRow = teamRowsByName.get(String(loser).toLowerCase());
  const winnerRecord = maddenNewsTeamRecordText(winnerRow);
  const loserRecord = maddenNewsTeamRecordText(loserRow);

  if (winnerRow && Number(winnerRow.losses || 0) === 0 && Number(winnerRow.wins || 0) >= 2) return `🔥 ${winner} stays undefeated at ${winnerRecord} after beating ${loser} ${winnerScore}-${loserScore}`;
  if (loserRow && Number(loserRow.wins || 0) === 0 && Number(loserRow.losses || 0) >= 2) return `📉 ${loser} falls to ${loserRecord} after losing ${winnerScore}-${loserScore} to ${winner}`;
  if (margin >= 21) return `🔥 ${winner} dominates ${loser} ${winnerScore}-${loserScore}${winnerRecord ? ` and moves to ${winnerRecord}` : ''}`;
  if (margin <= 3) return `⚡ ${winner} edges ${loser} ${winnerScore}-${loserScore}${winnerRecord ? ` and moves to ${winnerRecord}` : ''}`;
  return `⚡ ${winner} defeats ${loser} ${winnerScore}-${loserScore}${winnerRecord ? ` and moves to ${winnerRecord}` : ''}`;
}

function addMaddenNewsHeadline(bucket, text) {
  if (!text) return;
  bucket.push(String(text).trim());
}



