let maddenAutosyncTimer = null;
let maddenAutosyncRunning = false;

async function runDueMaddenAutosyncs(client) {
  if (maddenAutosyncRunning) return;
  maddenAutosyncRunning = true;
  try {
    const due = await pool.query(
      `SELECT mls.*, l.guild_id AS league_guild_id, l.league_name
       FROM madden_league_settings mls
       JOIN leagues l ON l.league_id = mls.league_id
       WHERE mls.autosync_enabled = TRUE
         AND (mls.next_sync_at IS NULL OR mls.next_sync_at <= NOW())
       ORDER BY mls.next_sync_at ASC NULLS FIRST
       LIMIT 10`
    );

    for (const row of due.rows) {
      const guildId = row.guild_id || row.league_guild_id;
      const guild = await client.guilds.fetch(guildId).catch(() => null);
      if (!guild) continue;
      const league = await getLeagueById(row.league_id);
      if (!league) continue;

      let run;
      try {
        run = await runMaddenExternalFetchSync(guild, league, { week: null });
      } catch (error) {
        run = { status: 'failed', source: row.sync_source || 'unknown', message: error.message || 'Autosync failed.', imported_teams: 0, imported_games: 0, imported_players: 0 };
      }
      await postMaddenSyncFeed(guild, league, run).catch(() => null);

      const interval = Math.max(Number(row.autosync_interval_minutes || 60), 15);
      await pool.query(
        `UPDATE madden_league_settings
         SET next_sync_at = NOW() + ($2::int * INTERVAL '1 minute'), updated_at = NOW()
         WHERE league_id = $1`,
        [row.league_id, interval]
      );
    }
  } catch (error) {
    console.error('Madden autosync loop failed:', error);
  } finally {
    maddenAutosyncRunning = false;
  }
}

function startMaddenAutosyncLoop(client) {
  if (maddenAutosyncTimer) clearInterval(maddenAutosyncTimer);
  maddenAutosyncTimer = setInterval(() => {
    runDueMaddenAutosyncs(client).catch(error => console.error('Madden autosync tick failed:', error));
  }, 60 * 1000);
  setTimeout(() => runDueMaddenAutosyncs(client).catch(() => null), 10 * 1000);
}


async function runMaddenExternalFetchSync(guild, league, options = {}) {
  const settings = await ensureMaddenLeagueSettings(league);
  const eaConnectionResult = await pool.query(
    `SELECT id FROM madden_ea_connections
     WHERE league_id = $1 AND provider = 'ea_direct' AND connection_status = 'connected'
     LIMIT 1`,
    [league.league_id]
  );

  if (settings.sync_source === 'ea_direct' || eaConnectionResult.rows.length) {
    return await runMaddenEaDirectSync(guild, league, options);
  }

  const runId = randomUUID();
  const source = normalizeMaddenSource(settings.sync_source || 'unlinked');

  await pool.query(
    `INSERT INTO madden_sync_runs (id, guild_id, league_id, source, status, week_label, message)
     VALUES ($1, $2, $3, $4, 'running', $5, $6)`,
    [runId, guild.id, league.league_id, source, options.week || null, 'External Madden sync started.']
  );

  if (!settings.external_url) {
    const message = 'No external URL linked. Use /madden link with a source URL first.';
    await pool.query(
      `UPDATE madden_sync_runs SET status = 'failed', message = $2, completed_at = NOW() WHERE id = $1`,
      [runId, message]
    );
    await pool.query(
      `UPDATE madden_league_settings SET last_sync_at = NOW(), last_sync_status = 'failed', last_sync_message = $2, updated_at = NOW() WHERE league_id = $1`,
      [league.league_id, message]
    );
    const failed = await pool.query(`SELECT * FROM madden_sync_runs WHERE id = $1 LIMIT 1`, [runId]);
    return failed.rows[0];
  }

  const endpoints = buildMaddenEndpointList(settings);
  const totals = { teams: 0, games: 0, players: 0 };
  const errors = [];
  let successfulEndpoints = 0;

  for (const endpoint of endpoints) {
    try {
      const payload = await fetchJsonWithTimeout(endpoint.url, { apiKey: settings.api_key });
      await pool.query(
        `INSERT INTO madden_sync_payloads (id, guild_id, league_id, sync_run_id, endpoint, payload_type, raw_payload)
         VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [randomUUID(), guild.id, league.league_id, runId, endpoint.url, endpoint.type, JSON.stringify(payload)]
      );

      const rows = extractMaddenRowsByType(payload, endpoint.type);
      if (!rows.length) {
        errors.push(endpoint.type + ': no rows found at ' + endpoint.url);
        continue;
      }

      const counts = await importMaddenRowsByType(guild, league, endpoint.type, rows, options.week || null);
      totals.teams += Number(counts.teams || 0);
      totals.games += Number(counts.games || 0);
      totals.players += Number(counts.players || 0);
      successfulEndpoints += 1;
    } catch (error) {
      errors.push(endpoint.type + ': ' + (error.message || 'fetch failed'));
    }
  }

  // Always keep local Discord team bridge updated too.
  await syncMaddenFranchises(guild, league).catch(error => errors.push('local team bridge: ' + error.message));
  await cleanupMaddenTradeBlockAfterRosterSync(guild.id, league.league_id).catch(error => errors.push('trade block cleanup: ' + error.message));

  const status = successfulEndpoints > 0 ? 'completed' : 'failed';
  const message = successfulEndpoints > 0
    ? 'External sync completed. Imported teams: ' + totals.teams + ', games: ' + totals.games + ', players: ' + totals.players + (errors.length ? '. Some endpoints had warnings.' : '.')
    : 'External sync failed. ' + errors.slice(0, 3).join(' | ');

  await pool.query(
    `UPDATE madden_sync_runs
     SET status = $2,
         message = $3,
         imported_teams = $4,
         imported_games = $5,
         imported_players = $6,
         completed_at = NOW()
     WHERE id = $1`,
    [runId, status, message, totals.teams, totals.games, totals.players]
  );

  await pool.query(
    `UPDATE madden_league_settings
     SET last_sync_at = NOW(),
         last_sync_status = $2,
         last_sync_message = $3,
         updated_at = NOW()
     WHERE league_id = $1`,
    [league.league_id, status, message]
  );

  const runResult = await pool.query(`SELECT * FROM madden_sync_runs WHERE id = $1 LIMIT 1`, [runId]);
  return runResult.rows[0];
}


async function runMaddenExternalSyncPlaceholder(guild, league, options = {}) {
  const settings = await ensureMaddenLeagueSettings(league);
  const runId = randomUUID();

  await pool.query(
    `INSERT INTO madden_sync_runs (id, guild_id, league_id, source, status, week_label, message)
     VALUES ($1, $2, $3, $4, 'running', $5, $6)`,
    [runId, guild.id, league.league_id, settings.sync_source || 'unlinked', options.week || null, 'Madden sync started.']
  );

  // V1 foundation: no external provider API is hardcoded yet.
  // This creates the import pipeline, sync log, and local franchise/team bridge.
  // Once the exact Neon/league export source is confirmed, this function becomes the real fetch/import worker.
  await syncMaddenFranchises(guild, league).catch(() => null);

  const teams = await pool.query(
    `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id = $2 ORDER BY team_name ASC`,
    [guild.id, league.league_id]
  );

  for (const team of teams.rows) {
    await pool.query(
      `INSERT INTO madden_imported_team_stats (guild_id, league_id, team_name, team_role_id, owner_user_id, wins, losses, ties)
       VALUES ($1, $2, $3, $4, $5, 0, 0, 0)
       ON CONFLICT (league_id, team_name)
       DO UPDATE SET team_role_id = $4, owner_user_id = $5, imported_at = NOW()`,
      [guild.id, league.league_id, team.team_name, team.team_role_id, team.owner_user_id || null]
    );
  }

  const message = settings.sync_source
    ? 'Sync foundation completed. Teams were bridged locally. External fetch/import worker is ready for provider wiring.'
    : 'No external Madden source linked yet. Use /madden link first. Local teams were still bridged.';

  await pool.query(
    `UPDATE madden_sync_runs
     SET status = 'completed',
         message = $2,
         imported_teams = $3,
         completed_at = NOW()
     WHERE id = $1`,
    [runId, message, teams.rows.length]
  );

  await pool.query(
    `UPDATE madden_league_settings
     SET last_sync_at = NOW(),
         last_sync_status = 'completed',
         last_sync_message = $2,
         updated_at = NOW()
     WHERE league_id = $1`,
    [league.league_id, message]
  );

  const runResult = await pool.query(`SELECT * FROM madden_sync_runs WHERE id = $1 LIMIT 1`, [runId]);
  return runResult.rows[0] || { id: runId, status: 'completed', message };
}

async function getMaddenImportedStatus(guildId, leagueId) {
  const [teams, games, players, runs] = await Promise.all([
    pool.query(`SELECT COUNT(*)::int AS count FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id = $2`, [guildId, leagueId]),
    pool.query(`SELECT COUNT(*)::int AS count FROM madden_imported_games WHERE guild_id = $1 AND league_id = $2`, [guildId, leagueId]),
    pool.query(`SELECT COUNT(*)::int AS count FROM madden_imported_players WHERE guild_id = $1 AND league_id = $2`, [guildId, leagueId]),
    pool.query(`SELECT * FROM madden_sync_runs WHERE guild_id = $1 AND league_id = $2 ORDER BY started_at DESC LIMIT 5`, [guildId, leagueId]),
  ]);

  return {
    teams: Number(teams.rows[0]?.count || 0),
    games: Number(games.rows[0]?.count || 0),
    players: Number(players.rows[0]?.count || 0),
    runs: runs.rows,
  };
}

function buildMaddenSyncSettingsEmbed(league, settings, status = null) {
  const maskedKey = settings.api_key ? 'Stored / hidden' : 'Not set';

  const embed = new EmbedBuilder()
    .setTitle('Madden Sync Settings • ' + league.league_name)
    .setColor(0x5865F2)
    .addFields(
      { name: 'Sync Source', value: settings.sync_source || 'Not linked', inline: true },
      { name: 'External Franchise ID', value: settings.external_franchise_id || 'Not set', inline: true },
      { name: 'API Key', value: maskedKey, inline: true },
      { name: 'External URL', value: settings.external_url || 'Not set', inline: false },
      { name: 'Sync Worker', value: 'EA Direct wizard stores connection state inside Discord. URL/JSON sync and manual imports remain available as fallback.', inline: false },
      { name: 'Last Sync', value: settings.last_sync_at ? String(settings.last_sync_at) : 'Never', inline: true },
      { name: 'Last Status', value: settings.last_sync_status || 'None', inline: true },
      { name: 'Last Message', value: settings.last_sync_message || 'No sync has run yet.', inline: false },
      { name: 'Autosync', value: settings.autosync_enabled ? 'Enabled every ' + String(settings.autosync_interval_minutes || 60) + ' minutes' : 'Disabled', inline: true },
      { name: 'Next Sync', value: settings.next_sync_at ? String(settings.next_sync_at) : 'Not scheduled', inline: true },
      { name: 'Sync Feed', value: settings.sync_feed_channel_id ? '<#' + settings.sync_feed_channel_id + '>' : 'Not set', inline: true }
    )
    .setFooter({ text: 'GG Sports • Madden External Sync' })
    .setTimestamp();

  if (status) {
    embed.addFields(
      { name: 'Imported Teams', value: String(status.teams), inline: true },
      { name: 'Imported Games', value: String(status.games), inline: true },
      { name: 'Imported Players', value: String(status.players), inline: true }
    );
  }

  return embed;
}

function buildMaddenSyncRunEmbed(league, run) {
  return new EmbedBuilder()
    .setTitle('Madden Sync Complete • ' + league.league_name)
    .setColor(run.status === 'failed' ? 0xED4245 : 0x57F287)
    .addFields(
      { name: 'Status', value: run.status || 'completed', inline: true },
      { name: 'Source', value: run.source || 'unlinked', inline: true },
      { name: 'Week', value: run.week_label || 'Not specified', inline: true },
      { name: 'Imported Teams', value: String(run.imported_teams || 0), inline: true },
      { name: 'Imported Games', value: String(run.imported_games || 0), inline: true },
      { name: 'Imported Players', value: String(run.imported_players || 0), inline: true },
      { name: 'Message', value: run.message || 'Sync run completed.', inline: false }
    )
    .setFooter({ text: 'GG Sports • Madden Sync Foundation' })
    .setTimestamp();
}


async function ensureMaddenLeagueSettings(league, options = {}) {
  await pool.query(
    `INSERT INTO madden_league_settings (league_id, guild_id, console, advance_schedule, neon_sportz_url, updated_at)
     VALUES ($1, $2, $3, $4, $5, NOW())
     ON CONFLICT (league_id)
     DO UPDATE SET
       console = COALESCE($3, madden_league_settings.console),
       advance_schedule = COALESCE($4, madden_league_settings.advance_schedule),
       neon_sportz_url = COALESCE($5, madden_league_settings.neon_sportz_url),
       updated_at = NOW()`,
    [league.league_id, league.guild_id, options.console || null, options.advance || null, options.neonSportzUrl || null]
  );

  const result = await pool.query(
    `SELECT * FROM madden_league_settings WHERE league_id = $1 LIMIT 1`,
    [league.league_id]
  );

  return result.rows[0] || {};
}

async function syncMaddenFranchises(guild, league) {
  const teamRoles = await getLeagueTeamRoles(league.league_id);

  for (const team of teamRoles) {
    const role = await guild.roles.fetch(team.role_id).catch(() => null);
    const owner = role?.members?.find(member => !member.user.bot) || null;

    await pool.query(
      `INSERT INTO madden_franchises (id, guild_id, league_id, team_role_id, team_name, owner_user_id, coach_name, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
       ON CONFLICT (league_id, team_role_id)
       DO UPDATE SET
         team_name = $5,
         owner_user_id = COALESCE($6, madden_franchises.owner_user_id),
         coach_name = COALESCE($7, madden_franchises.coach_name),
         updated_at = NOW()`,
      [randomUUID(), guild.id, league.league_id, team.role_id, team.role_name, owner?.id || null, owner?.displayName || null]
    );

    await pool.query(
      `INSERT INTO madden_team_stats (guild_id, league_id, team_role_id, season_label)
       VALUES ($1, $2, $3, 'Current')
       ON CONFLICT (league_id, team_role_id, season_label) DO NOTHING`,
      [guild.id, league.league_id, team.role_id]
    );
  }
}

async function getMaddenLeagueSummary(guild, league) {
  const settings = await ensureMaddenLeagueSettings(league);
  await syncMaddenFranchises(guild, league).catch(() => null);

  const teams = await pool.query(
    `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id = $2 ORDER BY team_name ASC`,
    [guild.id, league.league_id]
  );

  return { settings, teams: teams.rows };
}

function buildMaddenLeagueEmbed(league, summary) {
  return new EmbedBuilder()
    .setTitle('Madden League Hub • ' + league.league_name)
    .setColor(0x57F287)
    .addFields(
      { name: 'Platform / Console', value: summary.settings.console || 'Not set', inline: true },
      { name: 'Advance Schedule', value: summary.settings.advance_schedule || 'Not set', inline: true },
      { name: 'Teams Synced', value: String(summary.teams.length || 0), inline: true },
      { name: 'Sync Source', value: summary.settings.sync_source || 'Not linked', inline: true },
      { name: 'External Franchise ID', value: summary.settings.external_franchise_id || 'Not set', inline: true },
      { name: 'League Bridge', value: 'Uses existing GG Sports league roles, standings, sportsbook, activity, legacy, shop, avatar, and badge systems.', inline: false },
      { name: 'Next Commands', value: '/madden teams\\n/madden franchise\\n/game add\\n/game report', inline: false }
    )
    .setFooter({ text: 'GG Sports • Madden Foundation' })
    .setTimestamp();
}

function buildMaddenTeamsEmbed(league, teams) {
  const NL = String.fromCharCode(10);
  return new EmbedBuilder()
    .setTitle('Madden Teams • ' + league.league_name)
    .setColor(0x5865F2)
    .setDescription(teams.length
      ? teams.map(team => '**' + team.team_name + '** — ' + (team.owner_user_id ? '<@' + team.owner_user_id + '>' : 'Unassigned')).join(NL).slice(0, 4096)
      : 'No Madden teams synced yet. Add team roles with /league teamrole, then run /madden setup.')
    .setFooter({ text: 'GG Sports • Madden Teams' })
    .setTimestamp();
}

async function buildMaddenFranchiseEmbed(guild, league, teamRoleId = null, userId = null) {
  await syncMaddenFranchises(guild, league).catch(() => null);

  let franchise;
  if (teamRoleId) {
    const result = await pool.query(
      `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id::text = $2::text AND team_role_id = $3 LIMIT 1`,
      [guild.id, league.league_id, teamRoleId]
    );
    franchise = result.rows[0];
  } else if (userId) {
    const result = await pool.query(
      `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id::text = $2::text AND owner_user_id = $3 LIMIT 1`,
      [guild.id, league.league_id, userId]
    );
    franchise = result.rows[0];
  } else {
    const result = await pool.query(
      `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id::text = $2::text ORDER BY updated_at DESC LIMIT 1`,
      [guild.id, league.league_id]
    );
    franchise = result.rows[0];
  }

  if (!franchise) {
    return new EmbedBuilder()
      .setTitle('Madden Franchise')
      .setColor(0xED4245)
      .setDescription('No franchise found. Add league team roles with /league teamrole, then run /madden setup.')
      .setTimestamp();
  }

  const teamName = franchise.team_name;
  const [teamStatsResult, detailedRanks, leaders, topPlayers, recentGamesResult, nextGame, powerRankResult] = await Promise.all([
    pool.query(
      `SELECT *
       FROM madden_imported_team_stats
       WHERE guild_id = $1::text
         AND league_id::text = $2::text
         AND (
           LOWER(team_name) = LOWER($3)
           OR LOWER(team_name) = LOWER($4)
         )
       LIMIT 1`,
      [guild.id, league.league_id, teamName, getMaddenTeamAbbrev(teamName)]
    ),
    getMaddenTeamDetailedRanks(guild.id, league.league_id, teamName).catch(() => null),
    getMaddenTeamLeaders(guild.id, league.league_id, teamName).catch(() => []),
    getMaddenTeamTopPlayers(guild.id, league.league_id, teamName, 5).catch(() => []),
    pool.query(
      `SELECT *
       FROM madden_imported_games
       WHERE guild_id = $1::text
         AND league_id::text = $2::text
         AND (
           LOWER(home_team) = LOWER($3)
           OR LOWER(away_team) = LOWER($3)
           OR LOWER(home_team) = LOWER($4)
           OR LOWER(away_team) = LOWER($4)
         )
       ORDER BY
         CASE WHEN LOWER(status) = 'completed' THEN 0 ELSE 1 END,
         COALESCE(NULLIF(regexp_replace(week_label, '[^0-9]', '', 'g'), ''), '0')::int DESC,
         imported_at DESC
       LIMIT 3`,
      [guild.id, league.league_id, String(teamName).toLowerCase(), String(getMaddenTeamAbbrev(teamName) || '').toLowerCase()]
    ),
    findMaddenGameCenterGame(guild.id, league.league_id, teamName, null, null).catch(() => null),
    pool.query(
      `SELECT *
       FROM madden_power_rankings
       WHERE league_id::text = $1::text
         AND LOWER(team_name) = LOWER($2)
       LIMIT 1`,
      [league.league_id, teamName]
    ).catch(() => ({ rows: [] })),
  ]);

  const teamStats = teamStatsResult.rows?.[0] || {};
  const record = formatMaddenStandingsRecord(teamStats);
  const pf = Number(teamStats.points_for || 0);
  const pa = Number(teamStats.points_against || 0);
  const diff = pf - pa;
  const powerRank = powerRankResult?.rows?.[0] || null;
  const powerRankText = powerRank ? `Power Rank: #${powerRank.rank} ${formatMaddenPowerMovement(powerRank)}` : 'Power Rank: Not calculated';

  const leadersText = leaders.length
    ? leaders.map(item => `**${item.label}:** ${item.text}`).join('\n')
    : 'No team leaders found yet.';

  const topPlayersText = topPlayers.length
    ? topPlayers.map((player, index) => `${index + 1}. ${maddenPlayerDisplayName(player)} — ${player.position || 'UNK'} • ${player.overall || 'N/A'} OVR • ${maddenPlayerDevEmojiOnly(player.dev_trait)}`).join('\n')
    : 'No imported roster players found.';

  const recentGames = recentGamesResult.rows || [];
  const recentText = recentGames.length
    ? recentGames.map(game => formatMaddenGameResultForTeam(game, teamName)).join('\n')
    : 'No imported games found.';

  const nextGameText = nextGame
    ? `**${nextGame.week_label || 'Week TBD'}** ${nextGame.away_team} @ ${nextGame.home_team} — ${formatMaddenGameStatus(nextGame)}`
    : 'No featured game found.';

  return new EmbedBuilder()
    .setTitle(`Madden Franchise Hub • ${teamName} (${getMaddenTeamAbbrev(teamName) || 'NFL'})`)
    .setColor(0xFEE75C)
    .setDescription(`**${league.league_name}**`)
    .addFields(
      { name: 'Coach', value: franchise.owner_user_id ? '<@' + franchise.owner_user_id + '>' : 'Unassigned', inline: true },
      { name: 'Team Role', value: franchise.team_role_id ? '<@&' + franchise.team_role_id + '>' : 'Unassigned', inline: true },
      { name: 'Record', value: `${record}\nPF ${pf} | PA ${pa} | DIFF ${diff >= 0 ? '+' : ''}${diff}`, inline: true },
      { name: 'Power Rank', value: powerRankText, inline: true },
      { name: 'Team Rankings', value: buildMaddenDetailedRankText(detailedRanks), inline: false },
      { name: 'Team Leaders', value: leadersText.slice(0, 1024), inline: false },
      { name: 'Top Players', value: topPlayersText.slice(0, 1024), inline: false },
      { name: 'Recent / Upcoming Games', value: recentText.slice(0, 1024), inline: false },
      { name: 'Featured Game', value: nextGameText.slice(0, 1024), inline: false },
      { name: 'Franchise Tools', value: '`/madden team` • `/madden game` • `/madden leaders` • `/madden standings`', inline: false }
    )
    .setFooter({ text: 'GG Sports • Madden Franchise Hub' })
    .setTimestamp();
}




